// ---- Homepage stats — computed from real data, never hardcoded ----
// Only listings explicitly marked isReal:true count here. Sample/placeholder
// listings (used to show layout) are deliberately excluded so this number
// stays honest. Add isReal:true to a new listing and these update automatically —
// no manual editing of the hero numbers required.
function updateHeroStats(){
  const realListings = categories.flatMap(cat => cat.listings.filter(l => l.isReal));
  const businessCount = realListings.length;
  const regionSet = new Set(realListings.map(l => (l.loc || '').split(',')[1]?.trim()).filter(Boolean));

  const statBiz = document.getElementById('stat-businesses');
  const statRegions = document.getElementById('stat-regions');
  const statCats = document.getElementById('stat-categories');
  if(statBiz) statBiz.textContent = businessCount;
  if(statRegions) statRegions.textContent = regionSet.size;
  // Fixed at 10+ per your instruction — categories already open on the platform,
  // not tied to how many businesses have signed up yet.
  if(statCats) statCats.textContent = '10+';
}
updateHeroStats();

const catGrid = document.getElementById('cat-grid');
categories.forEach(cat => {
  const card = document.createElement('button');
  card.dataset.catId = cat.id;
  if(cat.bgImage){
    card.className = 'cat-card photo-cover';
    card.style.backgroundImage = `url(${cat.bgImage})`;
    card.innerHTML = `
      <div class="photo-caption">
        ${cat.photoShowTitle ? `<div class="photo-caption-title">${cat.title}</div>` : ''}
        ${cat.desc}
      </div>
    `;
  } else {
    card.className = 'cat-card';
    card.innerHTML = `
      <span class="cat-status status-${cat.status}">${cat.statusLabel}</span>
      <div class="cat-icon">${cat.icon}</div>
      <div class="cat-title">${cat.title}</div>
      <div class="cat-desc">${cat.desc}</div>
    `;
  }
  card.addEventListener('click', () => openCategory(cat.id));
  catGrid.appendChild(card);
});

// Quick filter row — the simplified "Food, Beauty, Shops, Services" chips from the
// marketplace checklist. Services groups the trade categories (engineering, auto, delivery).
const quickCats = [
  {label:'🍽️ Food', match:['food']},
  {label:'💈 Beauty', match:['beauty']},
  {label:'🛍️ Shops', match:['shops']},
  {label:'🔧 Services', match:['engineering','auto','delivery','transport']},
  {label:'🏗️ Build', match:['construction','materials']},
  {label:'🏠 Stays', match:['accommodation']},
  {label:'🎉 Leisure', match:['leisure']},
];
const quickCatsEl = document.getElementById('quick-cats');
quickCats.forEach(qc => {
  const chip = document.createElement('div');
  chip.className = 'quick-chip';
  chip.textContent = qc.label;
  chip.addEventListener('click', () => {
    const target = catGrid.querySelector(`[data-cat-id="${qc.match[0]}"]`);
    if(target){
      target.scrollIntoView({behavior:'smooth', block:'center'});
      qc.match.forEach(id => {
        const el = catGrid.querySelector(`[data-cat-id="${id}"]`);
        if(el){
          el.classList.add('pulse-highlight');
          setTimeout(()=>el.classList.remove('pulse-highlight'), 1200);
        }
      });
    }
  });
  quickCatsEl.appendChild(chip);
});

const mainView = document.getElementById('main-view');
const detail = document.getElementById('detail');
const detailTitle = document.getElementById('detail-title');
const detailSub = document.getElementById('detail-sub');
const regionFilter = document.getElementById('loc-filter-region');
const townFilter = document.getElementById('loc-filter-town');
const listingGrid = document.getElementById('listing-grid');
const backBtn = document.getElementById('back-btn');

let currentCat = null;
let currentRegion = 'All Namibia';
let currentTown = null; // null = no town narrowing, just region-level

function renderCategoryListings(){
  listingGrid.innerHTML = '';
  const filtered = sortByFeatured(currentCat.listings).filter(item => {
    if(currentRegion === 'All Namibia') return true;
    const [town, region] = (item.loc || '').split(',').map(s => s.trim());
    if(currentTown) return town === currentTown;
    return region === currentRegion;
  });

  if(!filtered.length){
    const empty = document.createElement('div');
    empty.className = 'empty-note';
    empty.textContent = `No ${currentCat.title.toLowerCase()} listed in ${currentTown || currentRegion} yet — try "All Namibia" or check back as we onboard more businesses.`;
    listingGrid.appendChild(empty);
    return;
  }

  filtered.forEach(item => listingGrid.appendChild(makeListingCard(currentCat, item)));

  const note = document.createElement('div');
  note.className = 'empty-note';
  note.textContent = currentCat.note;
  listingGrid.appendChild(note);
}

function renderTowns(regionName){
  townFilter.innerHTML = '';
  if(!regionName || regionName === 'All Namibia') return;
  const towns = NAMIBIA_REGIONS[regionName] || [];
  const allChip = document.createElement('span');
  allChip.className = 'loc-chip active';
  allChip.textContent = `All ${regionName}`;
  allChip.addEventListener('click', () => {
    townFilter.querySelectorAll('.loc-chip').forEach(c=>c.classList.remove('active'));
    allChip.classList.add('active');
    currentTown = null;
    renderCategoryListings();
  });
  townFilter.appendChild(allChip);
  towns.forEach(town => {
    const chip = document.createElement('span');
    chip.className = 'loc-chip';
    chip.textContent = town;
    chip.addEventListener('click', () => {
      townFilter.querySelectorAll('.loc-chip').forEach(c=>c.classList.remove('active'));
      chip.classList.add('active');
      currentTown = town;
      renderCategoryListings();
    });
    townFilter.appendChild(chip);
  });
}

function availBadgeHTML(av){
  if(!av) return '';
  const cls = (av.status === 'available' || av.status === 'open' || av.status === 'in_stock') ? 'available'
            : (av.status === 'limited') ? 'limited' : 'full';
  const dot = cls === 'available' ? '🟢' : cls === 'limited' ? '🟡' : '🔴';
  return `<div class="avail-badge ${cls}">${dot} ${av.detail}</div>`;
}

function makeListingCard(cat, item){
  const card = document.createElement('div');
  card.className = 'listing-card' + (item.featured ? ' is-featured' : '');
  const isVerified = item.kind === 'verified';
  const hasPhoto = item.photos && item.photos.length && item.photos[0].startsWith('blob:');
  const photoHTML = hasPhoto
    ? `<div class="listing-photo ${isVerified ? '' : 'soon'}" style="background-image:url('${item.photos[0]}'); background-size:cover; background-position:center;"></div>`
    : `<div class="listing-photo ${isVerified ? '' : 'soon'}">${item.icon}</div>`;
  card.innerHTML = `
    ${item.featured ? `<span class="featured-tag">🔥 Featured</span>` : ''}
    ${photoHTML}
    <div class="listing-body">
      <h4>${item.name}</h4>
      <div class="listing-loc">${item.loc}</div>
      ${availBadgeHTML(item.availability)}
      <span class="${isVerified ? 'badge-verified' : 'badge-placeholder'}">${isVerified ? '✓ Verified' : 'Sample layout'}</span>
      <div class="listing-price">${item.price}</div>
      <a class="listing-cta ${isVerified ? '' : 'ghost'}">${isVerified ? 'View shop' : 'Preview layout'}</a>
    </div>
  `;
  card.addEventListener('click', () => openBusiness(cat, item));
  return card;
}

// Featured listings (paid upgrade, N$150–200/month) sort first within any list.
// Stable sort — order within each group (featured / not featured) is preserved.
// No listing has featured:true by default — this only activates once a business
// actually pays for it and the flag is set on their entry.
function sortByFeatured(listings){
  return [...listings].sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0));
}

function openCategory(id){
  currentCat = categories.find(c => c.id === id);
  currentRegion = 'All Namibia';
  currentTown = null;
  detailTitle.innerHTML = `${currentCat.icon} ${currentCat.title}`;
  detailSub.textContent = currentCat.desc;

  regionFilter.innerHTML = '';
  const regionNames = ['All Namibia', ...Object.keys(NAMIBIA_REGIONS)];
  regionNames.forEach((region, i) => {
    const chip = document.createElement('span');
    chip.className = 'loc-chip' + (i===0 ? ' active' : '');
    chip.textContent = region;
    chip.addEventListener('click', () => {
      regionFilter.querySelectorAll('.loc-chip').forEach(c=>c.classList.remove('active'));
      chip.classList.add('active');
      currentRegion = region;
      currentTown = null;
      renderTowns(region);
      renderCategoryListings();
    });
    regionFilter.appendChild(chip);
  });
  renderTowns(null);
  renderCategoryListings();

  mainView.classList.add('hidden');
  business.classList.remove('active');
  detail.classList.add('active');
  window.scrollTo(0,0);
}

backBtn.addEventListener('click', () => {
  detail.classList.remove('active');
  mainView.classList.remove('hidden');
  window.scrollTo(0,0);
});

// ---- Business page (/shop/[slug] equivalent) ----
const business = document.getElementById('business');
const bizBackBtn = document.getElementById('biz-back-btn');
const bizLogo = document.getElementById('biz-logo');
const bizName = document.getElementById('biz-name');
const bizLoc = document.getElementById('biz-loc');
const bizAvailBadge = document.getElementById('biz-avail-badge');
const bizFeaturedTag = document.getElementById('biz-featured-tag');
const bizAvailNote = document.getElementById('biz-avail-note');
const qtyCheck = document.getElementById('qty-check');
const qtyCheckLabel = document.getElementById('qty-check-label');
const qtyValueEl = document.getElementById('qty-value');
const qtyMinusBtn = document.getElementById('qty-minus');
const qtyPlusBtn = document.getElementById('qty-plus');
const qtyResult = document.getElementById('qty-result');
let qtyCurrent = 1;
let qtyCurrentItem = null;
let qtyCurrentCat = null;

const QTY_UNIT_LABEL = { rooms: 'room', slots: 'slot', stock: 'item' };

function evaluateQty(){
  if(!qtyCurrentItem || !qtyCurrentItem.availability || qtyCurrentItem.availability.count === undefined) return;
  const count = qtyCurrentItem.availability.count;
  const unit = QTY_UNIT_LABEL[qtyCurrentCat.availType] || 'unit';
  qtyValueEl.textContent = qtyCurrent;
  if(qtyCurrent <= count){
    qtyResult.className = 'qty-result ok';
    const left = count - qtyCurrent;
    qtyResult.textContent = `✅ ${left} ${left === 1 ? unit : unit + 's'} would still be left after this.`;
    renderNearby(qtyCurrentCat, qtyCurrentItem); // normal framing, no override
  } else {
    qtyResult.className = 'qty-result warn';
    qtyResult.textContent = `⚠️ Only ${count} ${count === 1 ? unit : unit + 's'} available — that's not enough for ${qtyCurrent}. Showing similar options below.`;
    const reason = `${qtyCurrentItem.name} only has ${count} ${count === 1 ? unit : unit + 's'} available — not enough for the ${qtyCurrent} you need. Here are other ${qtyCurrentCat.title.toLowerCase()} options.`;
    renderNearby(qtyCurrentCat, qtyCurrentItem, reason);
  }
}

qtyMinusBtn.addEventListener('click', () => {
  if(qtyCurrent > 1){ qtyCurrent--; evaluateQty(); }
});
qtyPlusBtn.addEventListener('click', () => {
  qtyCurrent++; evaluateQty();
});
const bizAbout = document.getElementById('biz-about');
const bizMenuLabel = document.getElementById('biz-menu-label');
const bizMenu = document.getElementById('biz-menu');
const bizGallery = document.getElementById('biz-gallery');
const bizExpect = document.getElementById('biz-expect');
const bizExpectOffer = document.getElementById('biz-expect-offer');
const bizExpectDivider = document.getElementById('biz-expect-divider');
const bizExpectKnow = document.getElementById('biz-expect-know');
const bizNearby = document.getElementById('biz-nearby');
const bizNearbyWarn = document.getElementById('biz-nearby-warn');
const bizNearbyLabel = document.getElementById('biz-nearby-label');
const bizNearbyList = document.getElementById('biz-nearby-list');
const bizTracker = document.getElementById('biz-tracker');
const bizTrackerSteps = document.getElementById('biz-tracker-steps');
const bizPayment = document.querySelector('.biz-payment');
const bizOrderBtn = document.getElementById('biz-order-btn');
const bizNotJoined = document.getElementById('biz-not-joined');
const bizNote = document.getElementById('biz-note');

// Same category, same town first — falls back to same category, any town, if the town has no other listings.
// qtyOverrideReason: when set (from the quantity check), forces "Try These Instead" framing
// even if the business's own status isn't full/closed — used when the customer needs more
// than what's actually left.
function renderNearby(cat, item, qtyOverrideReason){
  const currentTown = (item.loc || '').split(',')[0].trim();
  let siblings = cat.listings.filter(l => l !== item && (l.loc || '').split(',')[0].trim() === currentTown);
  let sameTownOnly = true;
  if(!siblings.length){
    siblings = cat.listings.filter(l => l !== item);
    sameTownOnly = false;
  }
  siblings = siblings.slice(0, 5);
  const isFullOrClosed = item.availability && (item.availability.status === 'full' || item.availability.status === 'closed');
  const showOverflow = isFullOrClosed || !!qtyOverrideReason;
  if(siblings.length){
    bizNearby.style.display = 'block';
    if(showOverflow){
      bizNearbyWarn.style.display = 'block';
      bizNearbyWarn.textContent = qtyOverrideReason
        ? qtyOverrideReason
        : `${item.name} is showing ${item.availability.detail.toLowerCase()} right now — here are other ${cat.title.toLowerCase()} options${sameTownOnly ? ' nearby' : ''}.`;
      bizNearbyLabel.textContent = `Try These Instead`;
    } else {
      bizNearbyWarn.style.display = 'none';
      bizNearbyLabel.textContent = sameTownOnly ? `Other ${cat.title} Nearby` : `Other ${cat.title} in Namibia`;
    }
    bizNearbyList.innerHTML = '';
    siblings.forEach(sib => {
      const row = document.createElement('div');
      row.className = 'biz-nearby-item';
      row.innerHTML = `
        <div class="icon">${sib.icon}</div>
        <div class="info">
          <div class="name">${sib.name}</div>
          <div class="loc">${sib.loc}</div>
        </div>
        ${availBadgeHTML(sib.availability)}
      `;
      row.addEventListener('click', () => openBusiness(cat, sib));
      bizNearbyList.appendChild(row);
    });
    bizNearby.scrollIntoView({behavior:'smooth', block:'nearest'});
  } else {
    bizNearby.style.display = 'none';
  }
}

function openBusiness(cat, item){
  const isVerified = item.kind === 'verified';
  bizLogo.textContent = item.icon;
  bizName.textContent = item.name;
  bizLoc.textContent = `${cat.icon} ${cat.title} · ${item.loc}`;
  bizAvailBadge.innerHTML = availBadgeHTML(item.availability);
  bizFeaturedTag.innerHTML = item.featured ? `<span class="biz-featured-tag">🔥 Featured</span>` : '';
  bizAvailNote.style.display = item.availability ? 'block' : 'none';
  bizAbout.textContent = item.about || `Placeholder page for a ${cat.title.toLowerCase()} business. Once listed, the owner fills this in themselves from their dashboard.`;

  // ---- Quantity check — only shown when the listing has a real countable amount ----
  qtyCurrentItem = item;
  qtyCurrentCat = cat;
  if(item.availability && item.availability.count !== undefined){
    qtyCheck.style.display = 'block';
    qtyCurrent = 1;
    const unit = QTY_UNIT_LABEL[cat.availType] || 'unit';
    qtyCheckLabel.textContent = `How many ${unit}s do you need?`;
    qtyResult.className = 'qty-result';
    qtyResult.textContent = '';
    evaluateQty();
  } else {
    qtyCheck.style.display = 'none';
  }

  // ---- Photo gallery ----
  bizGallery.innerHTML = '';
  if(item.photos && item.photos.length){
    const [cover, ...rest] = item.photos;
    const isRealPhoto = cover.startsWith('blob:') || cover.startsWith('data:') || cover.startsWith('http');
    const coverEl = document.createElement('div');
    coverEl.className = 'biz-gallery-cover';
    if(isRealPhoto){
      coverEl.style.backgroundImage = `url('${cover}')`;
      coverEl.style.backgroundSize = 'cover';
      coverEl.style.backgroundPosition = 'center';
      coverEl.addEventListener('click', () => openLightbox(cover));
    } else {
      coverEl.textContent = cover;
    }
    bizGallery.appendChild(coverEl);
    if(rest.length){
      const grid = document.createElement('div');
      grid.className = 'biz-gallery-grid';
      rest.forEach(p => {
        const thumb = document.createElement('div');
        thumb.className = 'biz-gallery-thumb';
        if(isRealPhoto){
          thumb.style.backgroundImage = `url('${p}')`;
          thumb.style.backgroundSize = 'cover';
          thumb.style.backgroundPosition = 'center';
          thumb.addEventListener('click', () => openLightbox(p));
        } else {
          thumb.textContent = p;
        }
        grid.appendChild(thumb);
      });
      bizGallery.appendChild(grid);
    }
  } else {
    const empty = document.createElement('div');
    empty.className = 'biz-gallery-empty';
    empty.textContent = '📷 No photos added yet — businesses with clear photos get more enquiries.';
    bizGallery.appendChild(empty);
  }

  // ---- Menu + price breakdown ----
  bizMenu.innerHTML = '';
  const menu = item.menu || [{name:item.price, price:'', desc:''}];
  let total = 0;
  let hasPrices = true;
  menu.forEach(m => {
    const row = document.createElement('div');
    row.className = 'biz-menu-item';
    row.innerHTML = `
      <div>
        <div class="item-name">${m.name}</div>
        ${m.desc ? `<div class="item-desc">${m.desc}</div>` : ''}
      </div>
      ${m.price ? `<div class="item-price">${m.price}</div>` : ''}
    `;
    bizMenu.appendChild(row);
    const num = m.price ? parseInt(m.price.replace(/[^0-9]/g,''), 10) : NaN;
    if(!isNaN(num)) total += num; else hasPrices = false;
  });
  if(item.menu && hasPrices && menu.length > 1){
    const totalRow = document.createElement('div');
    totalRow.className = 'biz-menu-total';
    totalRow.innerHTML = `<span>If you got everything above</span><span>N$${total}</span>`;
    bizMenu.appendChild(totalRow);
    const note = document.createElement('div');
    note.className = 'biz-menu-note';
    note.textContent = 'Prices shown are what you pay — no hidden fees added at checkout.';
    bizMenu.appendChild(note);
  }
  bizMenuLabel.style.display = item.menu ? 'block' : 'none';
  bizMenu.style.display = item.menu ? 'block' : 'none';
  bizPayment.style.display = isVerified ? 'block' : 'none';

  // ---- What to expect / good to know ----
  if(item.whatToExpect || item.goodToKnow){
    bizExpect.style.display = 'block';
    bizExpectOffer.innerHTML = (item.whatToExpect || []).map(t => `<div class="expect-row">✅ ${t}</div>`).join('');
    if(item.goodToKnow && item.goodToKnow.length){
      bizExpectDivider.style.display = 'block';
      bizExpectKnow.innerHTML = item.goodToKnow.map(t => `<div class="expect-row good-know">ℹ️ ${t}</div>`).join('');
    } else {
      bizExpectDivider.style.display = 'none';
      bizExpectKnow.innerHTML = '';
    }
  } else {
    bizExpect.style.display = 'none';
  }

  // ---- Group framing / auto-referral overflow ----
  // Skipped here when the item has a countable quantity — evaluateQty() above already
  // called renderNearby() with the correct framing, and this would otherwise overwrite it.
  if(!(item.availability && item.availability.count !== undefined)){
    renderNearby(cat, item);
  }

  // ---- Order status tracker (illustrative only — no live order state yet) ----
  if(isVerified){
    bizTracker.style.display = 'block';
    const steps = ['Order Received','Confirmed by Business','Preparing','Ready / On the Way','Completed'];
    bizTrackerSteps.innerHTML = steps.map((label, i) => `
      <div class="tracker-row">
        <div class="tracker-dot-col">
          <div class="tracker-dot ${i===0 ? 'on' : ''}"></div>
          ${i < steps.length-1 ? '<div class="tracker-line"></div>' : ''}
        </div>
        <div class="tracker-label ${i===0 ? 'on' : ''}">${label}</div>
      </div>
    `).join('');
  } else {
    bizTracker.style.display = 'none';
  }

  bizOrderBtn.style.display = isVerified ? 'flex' : 'none';
  bizNotJoined.style.display = isVerified ? 'none' : 'block';
  bizNotJoined.textContent = `${item.name} hasn't joined allinone trust yet — you're viewing a sample layout so you can see how a real business page will look.`;
  bizNote.textContent = isVerified
    ? "This mirrors your /shop/[slug] page — banner, logo, about, menu with prices, and a WhatsApp order button."
    : "This category isn't live yet, so this page shows the intended layout rather than a real order button.";

  detail.classList.remove('active');
  business.classList.add('active');
  window.scrollTo(0,0);
}

bizBackBtn.addEventListener('click', () => {
  business.classList.remove('active');
  detail.classList.add('active');
  window.scrollTo(0,0);
});

// ---- Join wizard (Booking.com "list your property" style, 3 steps) ----
