const joinConfirmText = document.getElementById('join-confirm-text');
const joinWhatsappSendBtn = document.getElementById('join-whatsapp-send-btn');
const joinDoneBtn = document.getElementById('join-done-btn');
const joinCatGrid = document.getElementById('join-cat-grid');
const joinError = document.getElementById('join-error');
const joinRegionSelect = document.getElementById('join-region');
const joinTownSelect = document.getElementById('join-town');
