joinDescriptionInput.addEventListener('input', () => {
  const words = joinDescriptionInput.value.trim().split(/\s+/).filter(Boolean);
  joinDescCount.textContent = `(${words.length}/10 words)`;
  joinDescCount.style.color = words.length > 10 ? '#F87171' : '';
});

// ---- "Help me write this" — a simple, honest description assistant ----
// This is rule-based text shaping, NOT a real AI call. A genuine AI-generated
// version needs a server-side route calling an AI API with a securely stored
// key — that can't safely run in this static HTML file. This gives 3
// reasonable starting options from what they typed, clearly labeled as such.
document.getElementById('ai-help-btn').addEventListener('click', () => {
  const raw = prompt("Explain your business in your own words (a sentence or two):");
  if(!raw || !raw.trim()) return;

  const words = raw.trim().replace(/[.\n]+/g, ' ').split(/\s+/).filter(Boolean);
  const firstSix = words.slice(0, 6).join(' ');
  const keyWord = words.find(w => w.length > 4) || words[0] || 'quality service';

  const options = [
    `${firstSix}${words.length > 6 ? '...' : ''}`,
    `Trusted for ${keyWord.toLowerCase()}, here in Namibia`,
    `Quality ${keyWord.toLowerCase()}, fast WhatsApp ordering`,
  ].map(s => s.split(/\s+/).slice(0, 10).join(' '));

  const choice = prompt(
    "Here are 3 short options (this is simple text shaping, not real AI — reply 1, 2, or 3):\n\n" +
    `1) ${options[0]}\n2) ${options[1]}\n3) ${options[2]}`
  );
  const picked = options[parseInt(choice, 10) - 1];
  if(picked){
    joinDescriptionInput.value = picked;
    joinDescriptionInput.dispatchEvent(new Event('input'));
  }
});
const joinWhatsappInput = document.getElementById('join-whatsapp');

// ---- Business photo picker (demo: real file selection + local preview,
// no actual upload/storage since this file has no backend — that's the
// same honesty rule as everywhere else in this demo) ----
// One input, wired directly to a visible, real file picker.
const joinPhotoInput = document.getElementById('join-photo-input');
const photoDropLabel = document.getElementById('photo-drop-label');
const photoPreviewGrid = document.getElementById('photo-preview-grid');
const joinPhotoCount = document.getElementById('join-photo-count');
const MIN_JOIN_PHOTOS = 3;
const MAX_JOIN_PHOTOS = 5;
let joinPhotos = []; // { file, url }

function renderPhotoPreviews(){
  photoPreviewGrid.innerHTML = '';
  joinPhotos.forEach((p, i) => {
    const item = document.createElement('div');
    item.className = 'photo-preview-item';
    item.innerHTML = `<img src="${p.url}" alt="Photo ${i+1}"><div class="photo-remove-btn" data-i="${i}">×</div>`;
    item.querySelector('img').addEventListener('click', () => openLightbox(p.url));
    photoPreviewGrid.appendChild(item);
  });
  photoPreviewGrid.querySelectorAll('.photo-remove-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const i = parseInt(btn.dataset.i, 10);
      URL.revokeObjectURL(joinPhotos[i].url);
      joinPhotos.splice(i, 1);
      renderPhotoPreviews();
    });
  });
  joinPhotoCount.textContent = joinPhotos.length;
  photoDropLabel.style.display = joinPhotos.length >= MAX_JOIN_PHOTOS ? 'none' : 'block';
}

joinPhotoInput.addEventListener('change', (e) => {
  const files = Array.from(e.target.files || []);
  const room = MAX_JOIN_PHOTOS - joinPhotos.length;
  files.slice(0, room).forEach(file => {
    joinPhotos.push({ file, url: URL.createObjectURL(file) });
  });
  renderPhotoPreviews();
  joinPhotoInput.value = ''; // allow re-selecting the same file if removed
});

function resetJoinPhotos(){
  joinPhotos.forEach(p => URL.revokeObjectURL(p.url));
  joinPhotos = [];
  renderPhotoPreviews();
}

let joinStep = 1;
let joinSelectedCat = null;

// Build category picker (reuses the same categories used on the homepage)
categories.forEach(cat => {
  const pick = document.createElement('div');
  pick.className = 'cat-pick';
  pick.dataset.catId = cat.id;
  pick.innerHTML = `<span>${cat.icon}</span><span>${cat.title}</span>`;
  pick.addEventListener('click', () => {
    joinCatGrid.querySelectorAll('.cat-pick').forEach(el => el.classList.remove('selected'));
    pick.classList.add('selected');
    joinSelectedCat = cat.id;
    joinError.style.display = 'none';
    joinAccomFields.style.display = cat.id === 'accommodation' ? 'block' : 'none';
  });
  joinCatGrid.appendChild(pick);
});

const joinAccomFields = document.getElementById('join-accommodation-fields');
const joinRoomsTotal = document.getElementById('join-rooms-total');
const joinRoomsBooked = document.getElementById('join-rooms-booked');
const joinRoomsHint = document.getElementById('join-rooms-available-hint');

function updateRoomsHint(){
  const total = parseInt(joinRoomsTotal.value, 10);
  const booked = parseInt(joinRoomsBooked.value, 10);
  if(!isNaN(total) && !isNaN(booked)){
    const available = total - booked;
    joinRoomsHint.textContent = available >= 0
      ? `${available} of ${total} currently available`
      : `⚠️ Booked can't be more than total rooms/houses`;
  } else {
    joinRoomsHint.textContent = '';
  }
}
joinRoomsTotal.addEventListener('input', updateRoomsHint);
joinRoomsBooked.addEventListener('input', updateRoomsHint);

// Build region select
Object.keys(NAMIBIA_REGIONS).forEach(region => {
  const opt = document.createElement('option');
  opt.value = region; opt.textContent = region;
  joinRegionSelect.appendChild(opt);
});
function refreshJoinTowns(){
  joinTownSelect.innerHTML = '';
  const towns = NAMIBIA_REGIONS[joinRegionSelect.value] || [];
  towns.forEach(t => {
    const opt = document.createElement('option');
    opt.value = t; opt.textContent = t;
    joinTownSelect.appendChild(opt);
  });
}
joinRegionSelect.addEventListener('change', refreshJoinTowns);
refreshJoinTowns();

function renderJoinStep(){
  joinPanels.forEach((p, i) => p.classList.toggle('active', i === joinStep - 1));
  joinDots.forEach((d, i) => {
    d.classList.remove('done','current');
    if(i < joinStep - 1) d.classList.add('done');
    else if(i === joinStep - 1) d.classList.add('current');
  });
  const labels = ['Business Basics','Location','Contact & Photos','Payment'];
  joinStepLabel.textContent = `Step ${joinStep} of 4 — ${labels[joinStep-1]}`;
  joinBackStepBtn.style.visibility = joinStep === 1 ? 'hidden' : 'visible';
  joinNextBtn.textContent = joinStep === 4 ? 'Complete Listing' : 'Continue';
}

let preJoinContext = null;
let joinDoneTarget = null;

// Opens a category and re-applies a specific region/town filter — used to
// return someone to exactly where they were browsing after they join.
function openCategoryWithFilter(catId, region, town){
  openCategory(catId);
  if(region && region !== 'All Namibia'){
    currentRegion = region;
    regionFilter.querySelectorAll('.loc-chip').forEach(c => c.classList.toggle('active', c.textContent === region));
    renderTowns(region);
    if(town){
      currentTown = town;
      townFilter.querySelectorAll('.loc-chip').forEach(c => c.classList.toggle('active', c.textContent === town));
    }
    renderCategoryListings();
  }
}

function openJoin(){
  // Remember exactly where they were browsing, so finishing the join flow
  // can send them back there instead of just the homepage.
  if(detail.classList.contains('active') && currentCat){
    preJoinContext = { catId: currentCat.id, region: currentRegion, town: currentTown };
  } else {
    preJoinContext = null;
  }

  detail.classList.remove('active');
  business.classList.remove('active');
  mainView.classList.add('hidden');
  join.classList.add('active');
  joinConfirm.classList.remove('active');
  joinNav.style.display = 'flex';
  joinStep = 1;
  joinSelectedCat = null;
  joinCatGrid.querySelectorAll('.cat-pick').forEach(el => el.classList.remove('selected'));
  joinNameInput.value = '';
  joinWhatsappInput.value = '';
  joinDescriptionInput.value = '';
  joinDescCount.textContent = '(0/10 words)';
  joinDescCount.style.color = '';
  joinPaymentConfirm.checked = false;
  joinError.style.display = 'none';
  joinAccomFields.style.display = 'none';
  joinRoomsTotal.value = '';
  joinRoomsBooked.value = '';
  joinRoomsHint.textContent = '';
  resetJoinPhotos();
  renderJoinStep();
  window.scrollTo(0,0);
}

document.getElementById('header-join-btn').addEventListener('click', openJoin);

// Tap the logo from anywhere to return straight to the homepage —
// avoids needing multiple "Back" taps from deep inside a category or business page.
document.getElementById('header-logo').addEventListener('click', () => {
  detail.classList.remove('active');
  business.classList.remove('active');
  townResults.classList.remove('active');
  join.classList.remove('active');
  mainView.classList.remove('hidden');
  window.scrollTo(0,0);
});
document.getElementById('hero-join-btn').addEventListener('click', openJoin);
document.getElementById('hero-browse-btn').addEventListener('click', () => {
  document.getElementById('cat-grid').scrollIntoView({behavior:'smooth', block:'start'});
});

joinBackBtn.addEventListener('click', () => {
  join.classList.remove('active');
  mainView.classList.remove('hidden');
  window.scrollTo(0,0);
});

joinBackStepBtn.addEventListener('click', () => {
  if(joinStep > 1){ joinStep--; renderJoinStep(); }
});

joinNextBtn.addEventListener('click', () => {
  if(joinStep === 1){
    const name = joinNameInput.value.trim();

    // Rule 1: must select a category before continuing.
    if(!joinSelectedCat){
      joinError.style.display = 'block';
      joinError.textContent = '⚠️ Please select a business category before continuing.';
      return;
    }

    // Rule 2: same business name shouldn't already be listed under a different category —
    // catches accidental duplicate signups filed under the wrong category.
    if(name){
      const nameLower = name.toLowerCase();
      let conflict = null;
      for(const c of categories){
        if(c.id === joinSelectedCat) continue;
        const match = c.listings.find(l => l.name.toLowerCase() === nameLower);
        if(match){ conflict = c; break; }
      }
      if(conflict){
        joinError.style.display = 'block';
        joinError.textContent = `⚠️ "${name}" already appears under ${conflict.title}. If that's a mistake, message us on WhatsApp instead of submitting again — don't list the same business under two categories.`;
        return;
      }
    }

    // Rule 3: Accommodation businesses must specify total and booked rooms/houses.
    if(joinSelectedCat === 'accommodation'){
      const total = parseInt(joinRoomsTotal.value, 10);
      const booked = parseInt(joinRoomsBooked.value, 10);
      if(isNaN(total) || total < 1){
        joinError.style.display = 'block';
        joinError.textContent = '⚠️ Please enter how many rooms or houses you have in total.';
        return;
      }
      if(isNaN(booked) || booked < 0){
        joinError.style.display = 'block';
        joinError.textContent = '⚠️ Please enter how many are currently booked (use 0 if none).';
        return;
      }
      if(booked > total){
        joinError.style.display = 'block';
        joinError.textContent = "⚠️ Booked can't be more than your total rooms or houses.";
        return;
      }
    }

    joinError.style.display = 'none';
  }

  if(joinStep === 3){
    // Photo minimum must be met before moving to Payment.
    if(joinPhotos.length < MIN_JOIN_PHOTOS){
      joinError.style.display = 'block';
      joinError.textContent = `⚠️ Please add at least ${MIN_JOIN_PHOTOS} photos before continuing (${joinPhotos.length}/${MIN_JOIN_PHOTOS}).`;
      return;
    }
    // Brief description is mandatory, max 10 words.
    const descWords = joinDescriptionInput.value.trim().split(/\s+/).filter(Boolean);
    if(descWords.length === 0){
      joinError.style.display = 'block';
      joinError.textContent = '⚠️ Please write a brief description of your business (max 10 words).';
      return;
    }
    if(descWords.length > 10){
      joinError.style.display = 'block';
      joinError.textContent = `⚠️ Description is ${descWords.length} words — please shorten it to 10 words or fewer.`;
      return;
    }
    joinError.style.display = 'none';
  }

  if(joinStep < 4){
    joinStep++;
    renderJoinStep();
  } else {
    // Step 4 — Payment. Nothing goes live until this is checked, per the
    // decision that payment happens before a listing appears anywhere.
    if(!joinPaymentConfirm.checked){
      joinError.style.display = 'block';
      joinError.textContent = "⚠️ Please confirm you've sent payment before completing your listing.";
      return;
    }
    joinError.style.display = 'none';

    // Final step — the demo has no real backend/database, so this is the real
    // notification path: it builds a pre-filled WhatsApp message to allinone
    // trust's own number. The applicant taps Send in their own WhatsApp.
    const name = joinNameInput.value.trim() || 'Unnamed business';
    const catObj = categories.find(c => c.id === joinSelectedCat);
    const catLabel = catObj ? `${catObj.icon} ${catObj.title}` : 'Not selected';
    const region = joinRegionSelect.value || 'Not selected';
    const town = joinTownSelect.value || 'Not selected';
    const whatsapp = joinWhatsappInput.value.trim() || 'Not provided';
    const description = joinDescriptionInput.value.trim();
    const roomsLine = joinSelectedCat === 'accommodation'
      ? `\nRooms/Houses: ${joinRoomsTotal.value} total, ${joinRoomsBooked.value} booked (${joinRoomsTotal.value - joinRoomsBooked.value} available)`
      : '';

    const message =
`New allinone trust listing request 📋
Business: ${name}
Category: ${catLabel}
Location: ${town}, ${region}
Contact WhatsApp: ${whatsapp}
Description: ${description}${roomsLine}
Photos selected: ${joinPhotos.length} (attach separately in this chat — photos can't attach automatically)`;

    // allinone trust's own WhatsApp number, international format: 264 85 775 8227
    const OWNER_WHATSAPP = '264857758227';
    joinWhatsappSendBtn.href = `https://wa.me/${OWNER_WHATSAPP}?text=${encodeURIComponent(message)}`;

    // ---- Push this into the actual browsable data, for THIS browser session only ----
    // This is what makes "browse and see it" work immediately after joining —
    // but it resets the moment the page is reloaded or closed, since there's
    // still no real database. A real submission that survives a refresh needs
    // the Supabase backend already built separately for the real site.
    if(catObj){
      const newListing = {
        name: name,
        loc: `${town}, ${region}`,
        price: description,
        kind: 'verified',
        icon: catObj.icon,
        isReal: true,
        about: description,
        photos: joinPhotos.map(p => p.url),
      };
      if(joinSelectedCat === 'accommodation'){
        const total = parseInt(joinRoomsTotal.value, 10);
        const booked = parseInt(joinRoomsBooked.value, 10);
        const available = total - booked;
        newListing.availability = {
          status: available === 0 ? 'full' : available <= 1 ? 'limited' : 'available',
          detail: available === 0 ? 'Fully booked' : `${available} of ${total} available`,
          count: available,
          unit: 'room',
        };
      }
      catObj.listings.push(newListing);
      updateHeroStats(); // "Businesses live" / "Regions covered" update immediately
    }

    joinPanels.forEach(p => p.classList.remove('active'));
    joinNav.style.display = 'none';
    joinConfirmText.textContent = `You're now listed under ${catLabel} in ${town} for this session — tap "Done" to go see it. Also send this on WhatsApp so we actually receive your application, then attach your ${joinPhotos.length} photos to that same chat.`;
    joinConfirm.classList.add('active');
    joinDoneTarget = { catId: joinSelectedCat, region, town };
  }
});

joinDoneBtn.addEventListener('click', () => {
  join.classList.remove('active');
  if(joinDoneTarget){
    openCategoryWithFilter(joinDoneTarget.catId, joinDoneTarget.region, joinDoneTarget.town);
    joinDoneTarget = null;
  } else if(preJoinContext){
    openCategoryWithFilter(preJoinContext.catId, preJoinContext.region, preJoinContext.town);
  } else {
    mainView.classList.remove('hidden');
    window.scrollTo(0,0);
  }
});

// ---- Contact modal (secondary option next to WhatsApp — not a replacement) ----
const contactOverlay = document.getElementById('contact-overlay');
const contactFormView = document.getElementById('contact-form-view');
const contactConfirm = document.getElementById('contact-confirm');
const contactConfirmText = document.getElementById('contact-confirm-text');
const contactBizName = document.getElementById('contact-biz-name');
const contactNameInput = document.getElementById('contact-name');
const contactPhoneInput = document.getElementById('contact-phone');
const contactMessageInput = document.getElementById('contact-message');
let currentBizName = '';

