document.getElementById('contact-submit-btn').addEventListener('click', () => {
  // Demo only — nothing is sent or saved yet. Wire to Formspree/Supabase before going live.
  const name = contactNameInput.value.trim() || 'there';
  contactFormView.style.display = 'none';
  contactConfirmText.textContent = `Thanks, ${name} — ${currentBizName} will contact you shortly. (Demo note: this form doesn't send anywhere yet.)`;
  contactConfirm.classList.add('active');
});
document.getElementById('contact-done-btn').addEventListener('click', closeContactModal);

// ---- FAQ Assistant ----
// This is a rule-based keyword matcher, NOT a live/generative AI. It cannot
// answer anything outside this list. A real AI answering open-ended
// questions would need a server-side function calling an AI API with a
// securely stored key — that can't safely live in this static HTML file.
const FAQ = [
  { keywords: ['what is', 'what\'s this', 'about', 'allinone trust'],
    answer: "allinone trust is a directory that puts small businesses across Namibia online. Customers browse by category or region, then order straight through WhatsApp — no app needed." },
  { keywords: ['how does it work', 'how it works', 'how do i order', 'how to order'],
    answer: "Browse a category, open a business page, and tap 'Order on WhatsApp.' You chat directly with the business — allinone trust never handles the payment or the order itself." },
  { keywords: ['price', 'cost', 'how much', 'fee', 'n$'],
    answer: "N$250 once to get listed, plus N$50/month to stay active. An optional 'Featured' upgrade (shown first in your category) is N$150–200/month." },
  { keywords: ['list my business', 'join', 'sign up', 'add my business', 'get listed'],
    answer: "Tap 'List Your Business' at the top of the page — it's a quick 3-step form: business basics, location, then contact details. We review and get you live." },
  { keywords: ['pay', 'payment', 'cash', 'eft', 'card'],
    answer: "Businesses accept Cash on Delivery, Bank Transfer/EFT, or Pay at Shop. You pay the business directly — allinone trust never touches that money." },
  { keywords: ['where', 'region', 'area', 'town', 'location'],
    answer: "We're live in Kavango East and Khomas right now, with all 14 Namibian regions supported in the directory as we grow." },
  { keywords: ['whatsapp', 'contact', 'number', 'reach you'],
    answer: "You can reach allinone trust directly on WhatsApp: 085 7758 227, or Instagram @allinone.trust.905." },
  { keywords: ['real', 'legit', 'trust', 'genuine', 'scam'],
    answer: "allinone trust is run under 905 Company from Rundu. We're currently onboarding our first businesses — the directory shows sample layouts so you can see exactly how a real listing will look once businesses join." },
  { keywords: ['featured', 'trending', 'top'],
    answer: "'Featured' businesses are shown first in their category for N$150–200/month. It's optional — regular listings are always included in the base N$250 signup + N$50/month plan." },
];

const faqBubble = document.getElementById('faq-bubble');
const faqPanel = document.getElementById('faq-panel');
const faqMessages = document.getElementById('faq-messages');
const faqChips = document.getElementById('faq-chips');
const faqInput = document.getElementById('faq-input');

function faqAddMessage(text, sender){
  const msg = document.createElement('div');
  msg.className = `faq-msg ${sender}`;
  msg.textContent = text;
  faqMessages.appendChild(msg);
  faqMessages.scrollTop = faqMessages.scrollHeight;
}

function faqAnswer(question){
  const q = question.toLowerCase();
  const match = FAQ.find(f => f.keywords.some(k => q.includes(k)));
  return match ? match.answer : "I don't have an answer for that yet — message us directly on WhatsApp: 085 7758 227, and a real person will help.";
}

function faqAskChip(text){
  faqAddMessage(text, 'user');
  setTimeout(() => faqAddMessage(faqAnswer(text), 'bot'), 350);
}

function faqInit(){
  faqMessages.innerHTML = '';
  faqAddMessage("Hi! I can answer quick questions about how allinone trust works — pricing, how to list your business, payments, and more. What would you like to know?", 'bot');
  faqChips.innerHTML = '';
  ['How does it work?', 'How much does it cost?', 'How do I list my business?'].forEach(q => {
    const chip = document.createElement('div');
    chip.className = 'faq-chip';
    chip.textContent = q;
    chip.addEventListener('click', () => faqAskChip(q));
    faqChips.appendChild(chip);
  });
}

faqBubble.addEventListener('click', () => {
  faqInit();
  faqPanel.classList.add('active');
});
document.getElementById('faq-close-btn').addEventListener('click', () => {
  faqPanel.classList.remove('active');
});
faqPanel.addEventListener('click', (e) => {
  if(e.target === faqPanel) faqPanel.classList.remove('active');
});

function faqSend(){
  const text = faqInput.value.trim();
  if(!text) return;
  faqAddMessage(text, 'user');
  faqInput.value = '';
  setTimeout(() => faqAddMessage(faqAnswer(text), 'bot'), 350);
}
document.getElementById('faq-send-btn').addEventListener('click', faqSend);
faqInput.addEventListener('keypress', (e) => { if(e.key === 'Enter') faqSend(); });

// ---- Town/Location search (cross-category) ----
const searchRegionSelect = document.getElementById('search-region');
const searchTownSelect = document.getElementById('search-town');
const searchSubmitBtn = document.getElementById('search-submit-btn');
const townResults = document.getElementById('town-results');
const townResultsTitle = document.getElementById('town-results-title');
const townCatChips = document.getElementById('town-cat-chips');
const townListingGrid = document.getElementById('town-listing-grid');

Object.keys(NAMIBIA_REGIONS).forEach(region => {
  const opt = document.createElement('option');
  opt.value = region; opt.textContent = region;
  searchRegionSelect.appendChild(opt);
});
function refreshSearchTowns(){
  searchTownSelect.innerHTML = '';
  const towns = NAMIBIA_REGIONS[searchRegionSelect.value] || [];
  towns.forEach(t => {
    const opt = document.createElement('option');
    opt.value = t; opt.textContent = t;
    searchTownSelect.appendChild(opt);
  });
}
searchRegionSelect.addEventListener('change', refreshSearchTowns);
refreshSearchTowns();

let townActiveCat = 'all';

function renderTownResults(town){
  townResultsTitle.textContent = `Businesses in ${town}`;

  // Only categories that actually have a listing in this town get a chip.
  const matchingCats = categories.filter(cat =>
    cat.listings.some(l => (l.loc || '').split(',')[0].trim() === town)
  );

  townActiveCat = 'all';
  townCatChips.innerHTML = '';
  const allChip = document.createElement('div');
  allChip.className = 'town-cat-chip active';
  allChip.textContent = 'All';
  allChip.addEventListener('click', () => {
    townActiveCat = 'all';
    townCatChips.querySelectorAll('.town-cat-chip').forEach(c => c.classList.remove('active'));
    allChip.classList.add('active');
    renderTownListings(town);
  });
  townCatChips.appendChild(allChip);

  matchingCats.forEach(cat => {
    const chip = document.createElement('div');
    chip.className = 'town-cat-chip';
    chip.textContent = `${cat.icon} ${cat.title}`;
    chip.addEventListener('click', () => {
      townActiveCat = cat.id;
      townCatChips.querySelectorAll('.town-cat-chip').forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      renderTownListings(town);
    });
    townCatChips.appendChild(chip);
  });

  renderTownListings(town);

  mainView.classList.add('hidden');
  detail.classList.remove('active');
  business.classList.remove('active');
  townResults.classList.add('active');
  window.scrollTo(0,0);
}

function renderTownListings(town){
  townListingGrid.innerHTML = '';
  let matches = [];
  categories.forEach(cat => {
    if(townActiveCat !== 'all' && cat.id !== townActiveCat) return;
    cat.listings.forEach(item => {
      if((item.loc || '').split(',')[0].trim() !== town) return;
      matches.push({cat, item});
    });
  });
  matches = matches.sort((a, b) => (b.item.featured ? 1 : 0) - (a.item.featured ? 1 : 0));
  matches.forEach(({cat, item}) => townListingGrid.appendChild(makeListingCard(cat, item)));
  if(!matches.length){
    const note = document.createElement('div');
    note.className = 'empty-note';
    note.textContent = `No listings in ${town} yet for this filter — check back as we onboard more businesses.`;
    townListingGrid.appendChild(note);
  }
}

searchSubmitBtn.addEventListener('click', () => {
  renderTownResults(searchTownSelect.value);
});

document.getElementById('town-back-btn').addEventListener('click', () => {
  townResults.classList.remove('active');
  mainView.classList.remove('hidden');
  window.scrollTo(0,0);
});

// ---- Lightbox — opens any real photo full-size on tap ----
const lightboxOverlay = document.getElementById('lightbox-overlay');
const lightboxImg = document.getElementById('lightbox-img');

function openLightbox(url){
  lightboxImg.src = url;
  lightboxOverlay.classList.add('active');
}
document.getElementById('lightbox-close').addEventListener('click', () => {
  lightboxOverlay.classList.remove('active');
});
lightboxOverlay.addEventListener('click', (e) => {
  if(e.target === lightboxOverlay) lightboxOverlay.classList.remove('active');
});

